 async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});if(r.redirected||!r.headers.get('content-type')?.includes('application/json')){const failure=Error(!r.redirected&&r.status>=500?'Request failed. Try again.':'Session ended. Sign out and sign in again.');failure.status=!r.redirected&&r.status>=500?r.status:401;throw failure;}const data=await r.json();if(!r.ok){const failure=Error(data.error||'Request failed');failure.status=r.status;throw failure;}return data;}
 function updateTimerControls(){
  timerStop.disabled=timerBusy;timerRefresh.disabled=timerBusy;const losingFocus=document.activeElement===timerStop;timerStop.hidden=!timerKnown||!activeTimer;if(timerStop.hidden&&losingFocus)timerRefresh.focus();
  for(const b of main.querySelectorAll('[data-timer-project]')){const id=b.dataset.timerProject,name=b.dataset.projectName;b.disabled=timerBusy||!timerKnown||Boolean(activeTimer&&activeTimer.project_id!==id);b.textContent=!timerKnown?'Timer unavailable for '+name:activeTimer?.project_id===id?'Stop timer for '+name:activeTimer?'Timer running in another project':'Start timer for '+name;b.setAttribute('aria-label',activeTimer&&activeTimer.project_id!==id?'Timer running in another project; '+name:b.textContent);}
  for(const b of main.querySelectorAll('[data-timer-start]'))b.disabled=timerBusy||!timerKnown||Boolean(activeTimer);
  for(const b of main.querySelectorAll('[data-time-stop]'))b.disabled=timerBusy||!timerKnown||activeTimer?.id!==b.dataset.timeStop;
 }
 async function syncTimer(){
  if(actor?.role!=='staff'){timerPanel.hidden=true;return false;}if(timerBusy)return false;const attempt=++timerGeneration;timerPanel.hidden=false;timerPanel.setAttribute('aria-busy','true');
  try{const data=await api('timer/current');if(attempt!==timerGeneration||timerBusy)return false;activeTimer=data.item;timerKnown=true;timerPanel.dataset.timerId=activeTimer?.id||'';timerSummary.textContent=activeTimer?'Tracking '+activeTimer.project_name+' since '+new Date(activeTimer.started_at).toLocaleString('en-CA',{timeZone:'America/Toronto'}):'No running timer.';timerPanel.querySelector('[role=alert]')?.remove();updateTimerControls();return true;}
  catch(e){if(attempt!==timerGeneration)return false;if(!timerKnown)timerSummary.textContent='Unable to recover the active timer.';error(e.message,timerPanel);updateTimerControls();return false;}
  finally{if(attempt===timerGeneration)timerPanel.removeAttribute('aria-busy');}
 }
 async function changeTimer(path,body){
  if(timerBusy)return;timerBusy=true;++timerGeneration;timerPanel.setAttribute('aria-busy','true');updateTimerControls();let failure;
  try{await api(path,'POST',body);}catch(e){if(!(path.endsWith('/stop')&&e.status===404)&&!(path==='timer/start'&&e.status===409))failure=e;}
  finally{timerBusy=false;await syncTimer();updateTimerControls();}if(failure)throw failure;
 }
 function projectTimer(record,state){const b=node('button');b.type='button';b.className='secondary';b.dataset.timerProject=record.id;b.dataset.projectName=record.name;b.onclick=async()=>{if(!current(state)||timerBusy||!timerKnown||(activeTimer&&activeTimer.project_id!==record.id))return;const returnFocus=document.activeElement===b;try{await changeTimer(activeTimer?'timer/'+activeTimer.id+'/stop':'timer/start',activeTimer?{}:{projectId:record.id});}catch(e){if(current(state))error(e.message);}finally{updateTimerControls();if(returnFocus&&current(state)&&document.activeElement===document.body)(b.disabled?timerRefresh:b).focus();}};return b;}
 function captureTimeDraft(state){if(state?.page!=='time')return;const form=main.querySelector('form[data-time-form]');if(form)state.timeDraft={...Object.fromEntries(new FormData(form)),billable:form.elements.billable?.checked??true};}
