 timerStop.onclick=async()=>{const state=view,id=activeTimer?.id,returnFocus=document.activeElement===timerStop;if(!id||timerBusy)return;const focus=()=>{if(returnFocus&&current(state)&&document.activeElement===document.body)timerRefresh.focus();};try{await changeTimer('timer/'+id+'/stop',{});focus();if(state?.page==='time')await refresh(state);}catch(e){if(current(state))error(e.message,timerPanel);}finally{focus();}};
 window.addEventListener('focus',()=>{if(actor?.role==='staff')syncTimer();});
 function error(message,container=main){let e=container.querySelector('[role=alert]');if(!e){e=node('p',undefined,'error');e.setAttribute('role','alert');container.prepend(e);}e.textContent=message;}
