 async function listAll(type){let items=[],after='';for(let i=0;i<20;i++){const r=await api(type+(after?(type.includes('?')?'&':'?')+'after='+encodeURIComponent(after):''));items.push(...r.items);if(!r.nextCursor)return items;after=r.nextCursor;}throw Error('Selection exceeds pilot limit. Export and contact the administrator.');}
