 function recordForm(record,container=main,state=view){const {page,parents,staff}=state;if(actor.role!=='staff'||!['clients','projects','tasks','notes'].includes(page))return;const panel=node('section',undefined,'panel');panel.append(node('h2',(record?'Edit ':'Add ')+({clients:'client',projects:'project',tasks:'task',notes:'document'})[page]));const form=document.createElement('form');if(page==='notes'&&!record){form.setAttribute('data-document-create','');for(const event of ['input','change'])form.addEventListener(event,()=>{form.dataset.dirty='true';});}
  field(form,['clients','projects'].includes(page)?'name':'title','Name');
  if(page==='projects')field(form,'clientId','Client','text',parents);
  if(['tasks','notes'].includes(page))field(form,'projectId','Project','text',parents);
  if(page==='clients'){field(form,'email','Contact email','email').required=false;field(form,'company','Company').required=false;}
  if(page==='projects')field(form,'status','Status','text',['planned','active','complete'].map(id=>({id,name:id}))).value='active';
  if(page==='tasks'){field(form,'status','Status','text',['todo','doing','done'].map(id=>({id,name:id}))).value='todo';field(form,'assigneeId','Assigned to','text',staff).required=false;field(form,'dueOn','Due date','date').required=false;}
  if(page==='notes'){const parent=field(form,'parentId','Parent document','text',[]);parent.required=false;const selected=state.documentParents.find(n=>n.id===state.documentOptions.parentId);form.elements.projectId.value=record?.project_id||state.documentDraft?.projectId||selected?.project_id||state.documentOptions.projectId||'';documentParents(form,record,state,parent);parent.value=record?(record.parent_id||''):(state.documentDraft?.parentId??selected?.id??'');form.elements.projectId.onchange=()=>documentParents(form,record,state,parent);field(form,'text','Content','textarea');}
  if(page!=='clients')field(form,'clientVisible','Share with client','checkbox');
  if(record){for(const input of form.elements){const column=({clientId:'client_id',projectId:'project_id',clientVisible:'client_visible',assigneeId:'assignee_id',dueOn:'due_on',parentId:'parent_id'})[input.name]||input.name;if(input.type==='checkbox')input.checked=Boolean(record[column]);else input.value=record[column]??'';if(['clientId','projectId'].includes(input.name))input.disabled=true;}}
  if(page==='notes'&&!record&&state.documentDraft){for(const input of form.elements){if(input.type==='checkbox')input.checked=Boolean(state.documentDraft[input.name]);else if(input.name in state.documentDraft)input.value=state.documentDraft[input.name];}}
  const save=node('button','Save');save.type='submit';form.append(save);form.onsubmit=async e=>{e.preventDefault();if(!current(state))return;save.disabled=true;try{const body=Object.fromEntries(new FormData(form));if(page!=='clients')body.clientVisible=form.elements.clientVisible.checked;if(page==='tasks'){body.assigneeId=body.assigneeId||null;body.dueOn=body.dueOn||null;}if(page==='notes')body.parentId=body.parentId||null;if(record)body.revision=record.revision;await api(page+(record?'/'+record.id:''),record?'PATCH':'POST',body);if(record)container.close();else if(page==='notes'){state.discardDocumentDraft=true;state.documentOptions={q:'',projectId:body.projectId,parentId:body.parentId||'root',includeArchived:false};}await refresh(state,Boolean(record));}catch(err){if(current(state))error(err.message,form);}finally{save.disabled=false;}};panel.append(form);container.append(panel);
 }
 function editRecord(record,opener,state){const {page}=state;const dialog=node('dialog');dialog.setAttribute('aria-label','Edit '+({clients:'client',projects:'project',tasks:'task',notes:'document'})[page]);recordForm(record,dialog,state);dialog.append(button('Cancel',()=>dialog.close(),true,state));dialog.addEventListener('close',()=>{dialog.remove();if(current(state)&&opener?.isConnected)opener.focus();},{once:true});main.append(dialog);dialog.showModal();}

 function fileForm(state){const {parents}=state;if(actor.role!=='staff')return;const panel=node('section',undefined,'panel'),form=document.createElement('form');panel.append(node('h2','Upload private file'));field(form,'projectId','Project','text',parents);field(form,'original','File (maximum 5 MiB)','file');field(form,'clientVisible','Share with client','checkbox');const save=node('button','Upload file');save.type='submit';form.append(save);form.onsubmit=async e=>{e.preventDefault();if(!current(state))return;save.disabled=true;try{const file=form.elements.original.files[0];if(!file||file.size<1||file.size>5242880)throw Error('Choose a file between 1 byte and 5 MiB.');const r=await fetch('/api/files',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-Project-Id':form.elements.projectId.value,'X-File-Name':encodeURIComponent(file.name),'X-Client-Visible':String(form.elements.clientVisible.checked)},body:file});if(r.redirected||!r.headers.get('content-type')?.includes('application/json'))throw Error('Session ended. Sign in again.');const data=await r.json();if(!r.ok)throw Error(data.error||'Upload failed');await refresh(state,true);}catch(err){if(current(state))error(err.message,form);}finally{save.disabled=false;}};panel.append(form);main.append(panel);}
 function documentVersions(record,opener,state){
  const dialog=node('dialog'),heading=node('div',undefined,'row'),list=node('section'),preview=node('section');let versions=[],cursor=null,currentRevision=record.revision,listGeneration=0,previewGeneration=0,selected=null,older;
  dialog.className='history-dialog';dialog.setAttribute('aria-label','Version history for '+record.title);list.className='version-list';list.tabIndex=0;list.setAttribute('aria-label','Document versions');preview.setAttribute('aria-label','Version preview');preview.tabIndex=-1;
  const valid=()=>current(state)&&dialog.isConnected&&dialog.open;
  heading.append(node('h2','Version history'),button('Close history',()=>dialog.close(),true,state));dialog.append(heading,node('p',record.title),button('Reload version history',()=>loadVersions(),true,state),list,preview);
  function renderVersions(){
   list.replaceChildren();if(!versions.length)list.append(node('p','No saved versions yet.'));
   for(const version of versions){const item=node('article',undefined,'item'),view=button('View version '+version.revision,()=>loadPreview(version.revision),true,state);view.dataset.version=version.revision;view.setAttribute('aria-pressed',String(selected===version.revision));item.append(view,node('p',(version.revision===currentRevision?'Current · ':'')+(version.actor_id||'Author unknown')+' · '+(version.recorded_at===null?'Recorded date unknown':new Date(version.recorded_at).toLocaleString('en-CA',{timeZone:'America/Toronto'})),'help'));if(version.source_revision!==null)item.append(node('p','Restored from version '+version.source_revision,'help'));list.append(item);}
   older?.remove();older=cursor?button('Load older versions',()=>loadVersions(cursor),true,state):null;if(older)list.after(older);
  }
  async function loadVersions(before){
   if(!valid())return;const generation=++listGeneration;list.setAttribute('aria-busy','true');if(!before){++previewGeneration;selected=null;versions=[];cursor=null;older?.remove();older=null;preview.removeAttribute('aria-busy');preview.replaceChildren(node('p','Choose a version to review its content.','help'));list.replaceChildren(node('p','Loading versions…'));}
   try{const result=await api('notes/'+record.id+'/versions'+(before?'?before='+encodeURIComponent(before):''));if(!valid()||generation!==listGeneration)return;versions=before?[...versions,...result.items]:result.items;cursor=result.nextCursor;currentRevision=result.currentRevision;renderVersions();}
   catch(err){if(valid()&&generation===listGeneration){error(err.message,list);if(!before)list.append(button('Retry history',()=>loadVersions(),true,state));}}
   finally{if(valid()&&generation===listGeneration)list.removeAttribute('aria-busy');}
  }
  async function loadPreview(version){
   if(!valid())return;const generation=++previewGeneration;selected=version;for(const b of list.querySelectorAll('[data-version]'))b.setAttribute('aria-pressed',String(Number(b.dataset.version)===version));preview.setAttribute('aria-busy','true');preview.replaceChildren(node('p','Loading version…'));
   try{
    const snapshot=await api('notes/'+record.id+'/versions/'+version);if(!valid()||generation!==previewGeneration)return;
    const text=node('p',snapshot.text,'version-content'),form=document.createElement('form');text.tabIndex=0;text.setAttribute('aria-label','Version content');
    preview.replaceChildren(node('h3',snapshot.title),node('p','Version '+snapshot.revision+' · Current version '+snapshot.currentRevision,'help'),text);
    const shared=field(form,'clientVisible','Share restored document with client','checkbox'),save=node('button','Restore version '+snapshot.revision);save.type='submit';save.disabled=snapshot.revision===snapshot.currentRevision;form.append(node('p','Restoring creates a new version. Review the content and sharing choice before restoring.','help'),save);preview.append(form);let stale=false;
    form.onsubmit=async e=>{e.preventDefault();if(!valid()||generation!==previewGeneration||stale)return;save.disabled=true;shared.disabled=true;
     try{await api('notes/'+record.id+'/versions/'+snapshot.revision+'/restore','POST',{revision:snapshot.currentRevision,clientVisible:shared.checked});if(!valid()||generation!==previewGeneration)return;dialog.close();await refresh(state,true);}
     catch(err){if(valid()&&generation===previewGeneration){if(err.status===409)stale=true;error(stale?'Document changed. Reload version history before restoring.':err.message,form);}}
     finally{save.disabled=stale||snapshot.revision===snapshot.currentRevision;shared.disabled=false;}
    };preview.focus();
   }catch(err){if(valid()&&generation===previewGeneration){error(err.message,preview);preview.append(button('Retry version',()=>loadPreview(version),true,state));}}
   finally{if(valid()&&generation===previewGeneration)preview.removeAttribute('aria-busy');}
  }
  dialog.addEventListener('close',()=>{dialog.remove();if(current(state)&&opener?.isConnected)opener.focus();},{once:true});main.append(dialog);dialog.showModal();loadVersions();
 }
 function taskComments(record,opener,state){
  const dialog=node('dialog'),thread=node('section'),form=document.createElement('form');let comments=[],cursor=null,requestGeneration=0,attempt=null,older;
  dialog.setAttribute('aria-label','Comments for '+record.title);dialog.className='comment-dialog';thread.setAttribute('aria-label','Task comments');thread.className='comment-thread';thread.tabIndex=0;
  const valid=()=>current(state)&&dialog.isConnected&&dialog.open;
  const heading=node('div',undefined,'row');heading.append(node('h2','Task comments'),button('Close comments',()=>dialog.close(),true,state));dialog.append(heading,node('p',record.title),thread);
  const content=field(form,'content','Comment','textarea');content.maxLength=10000;
  const shared=actor.role==='staff'?field(form,'clientVisible','Share with client','checkbox'):null;
  form.prepend(node('p',shared?'Comments stay internal unless you choose Share with client.':'Your replies are shared with the permitted participants in this task.','help'));
  const save=node('button','Post comment');save.type='submit';form.append(save);dialog.append(form);
  function renderThread(){
   thread.replaceChildren(node('p',comments.length?'Newest comments first.':'No comments yet.','help'));
   for(const comment of comments){const item=node('article',undefined,'item'),line=node('div',undefined,'row');line.append(node('strong',comment.actor_id===actor.id?'You':comment.actor_id),node('span',comment.client_visible?'Shared with client':'Internal','badge'));const date=new Date(comment.created_at),time=node('time',date.toLocaleString('en-CA',{timeZone:'America/Toronto'}),'muted');time.dateTime=date.toISOString();item.append(line,node('p',comment.content),time);thread.append(item);}
   older?.remove();older=cursor?button('Load older comments',()=>loadComments(cursor),true,state):null;if(older)thread.after(older);
  }
  async function loadComments(after){
   if(!valid())return false;const generation=++requestGeneration;thread.setAttribute('aria-busy','true');if(!after)thread.replaceChildren(node('p','Loading comments…'));
   try{const result=await api('tasks/'+record.id+'/comments'+(after?'?after='+encodeURIComponent(after):''));if(!valid()||generation!==requestGeneration)return false;comments=after?[...comments,...result.items]:result.items;cursor=result.nextCursor;renderThread();return true;}
   catch(err){if(valid()&&generation===requestGeneration){error(err.message,thread);if(!after)thread.append(button('Retry comments',()=>loadComments(),true,state));}return false;}
   finally{if(valid()&&generation===requestGeneration)thread.removeAttribute('aria-busy');}
  }
  form.onsubmit=async e=>{
   e.preventDefault();if(!valid())return;const text=content.value.trim(),clientVisible=shared?shared.checked:true;
   if(!attempt||attempt.content!==text||attempt.clientVisible!==clientVisible)attempt={content:text,clientVisible,requestId:crypto.randomUUID()};
   const body=attempt;save.disabled=content.disabled=true;if(shared)shared.disabled=true;
   try{await api('tasks/'+record.id+'/comments','POST',body);if(!valid())return;attempt=null;content.value='';if(shared)shared.checked=false;form.querySelector('[role=alert]')?.remove();const refreshed=await loadComments();if(refreshed&&valid())content.focus();}
   catch(err){if(valid())error(err.message,form);}
   finally{save.disabled=content.disabled=false;if(shared)shared.disabled=false;}
  };
  dialog.addEventListener('close',()=>{dialog.remove();if(current(state)&&opener?.isConnected)opener.focus();},{once:true});main.append(dialog);dialog.showModal();content.focus();loadComments();
 }
