  if(route()==='notes'&&view?.page==='notes')captureDocumentDraft(view);
  const target=readRoute(),page=target.page,state={page,routeKey:target.key,recordId:target.recordId,linkError:target.linkError,generation:++generation,rows:[],parents:[],staff:[],cursor:null,timeManualAttempt:page==='time'&&view?.page===page?view.timeManualAttempt:null,timeReviewOpen:page==='time'&&view?.page===page?view.timeReviewOpen:false,timeReviewOptions:page==='time'&&view?.page===page?view.timeReviewOptions:null,timeDraft:page==='time'&&view?.page===page?view.timeDraft:null,documentParents:[],documentDraft:page==='notes'&&view?.page===page&&!view.discardDocumentDraft?view.documentDraft:null,documentOptions:page==='notes'&&view?.page===page?{...view.documentOptions}:{q:'',projectId:'',parentId:'*',includeArchived:false},taskOptions:page==='tasks'&&view?.page===page?{...view.taskOptions}:{layout:'list',project:'',status:'',assignee:''}};
